\begin{tikzpicture}[x=0.55cm,y=0.55cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-5.5,-4.5) rectangle (6.8,6.2);
\draw[->,line width=0.5pt] (-5,0)--(5.8,0) node[below] {$x$};
\draw[->,line width=0.5pt] (0,-4)--(0,5.8) node[left] {$y$};
\draw[dashed,line width=0.4pt] (-5,1)--(5,1) node[right] {$y=1$};
\begin{scope}\clip (-5,-4) rectangle (5,5.5);
\draw[line width=0.8pt,domain=-5:-0.4,samples=120] plot (\x,{2/\x+1});
\draw[line width=0.8pt,domain=0.44:5,samples=120] plot (\x,{2/\x+1});\end{scope}
\fill (-2,0) circle (1.5pt) node[below left] {$(-2,0)$};
\fill (1,3) circle (1.5pt) node[right] {$(1,3)$};
\node[anchor=north east] at (5.4,5.6) {$y=\frac{2}{x}+1$};
\end{tikzpicture}

